import{j as e}from"./blog-pages-Bhdy2a24.js";import{V as t}from"./_VerticalTemplate-CDHk-7EY.js";import"./accordion-BzzOwuN-.js";import"./index-DVDcNMDM.js";import"./dt-3d-models-Bs-XLBzm.js";import"./index-nWpZtNLo.js";const i={slug:"data-centers",industryDisplay:"Data Centers",industryShort:"hyperscale data center operators, colocation providers, and EPCs",heroSubhead:"Crew-level NDT cohorts for hyperscale data center construction and operation — structural steel welds (AWS D1.1), high-current bus-bar and switchgear connections (AWS D1.6), liquid-cooling piping (ASME B31.9), backup-power generator pressure systems (ASME B31.3), and the seismic-restraint inspection toolkit. Designed for AWS, Microsoft Azure, Google Cloud, Meta, and Equinix capital-deployment teams.",primaryStandards:["AWS D1.1 (structural steel)","AWS D1.6 (stainless steel)","ASME B31.3 (process piping — generator fuel + lube)","ASME B31.9 (building services piping)","ASME Section V","NFPA 70 (NEC)","TIA-942 (data center infrastructure)","IEC 61936-1 (HV installations)"],methods:[{method:"Ultrasonic Testing — PAUT for structural steel + thick-section bus-bar joints",levels:"Level II → III",roleFit:"Structural-steel weld QC, bus-bar joint inspectors, generator-skid fabrication QC",codeRef:"ASME V Article 4, AWS D1.1 Clause 6, AWS D1.6"},{method:"Magnetic Particle Testing — yoke + WFMT for structural / seismic welds",levels:"Level I → II",roleFit:"Structural steel inspectors, generator-mount + seismic-restraint QC",codeRef:"ASME V Article 7, AWS D1.1 Clause 8, ASTM E709"},{method:"Liquid Penetrant Testing — stainless / aluminium liquid-cooling pipe welds",levels:"Level I → II",roleFit:"Liquid-cooling system QC, immersion-tank weld inspectors",codeRef:"ASME V Article 6, ASTM E165, ASTM E1417"},{method:"Visual Testing — structural-steel acceptance + cable-tray + bus-duct visual QC",levels:"Level I → II",roleFit:"Site QC engineers, commissioning inspectors",codeRef:"ASME V Article 9, AWS D1.1 Clause 6.9, ISO 17637"},{method:"Radiographic Testing — generator-fuel + emergency-power piping welds",levels:"Level I → II",roleFit:"Generator-fuel-line QC, emergency-services piping inspectors",codeRef:"ASME V Article 2, ASME B31.3, ASME B31.9"},{method:"Infrared thermography — bus-bar joint surveillance + cable termination QC",levels:"Level II specialist",roleFit:"Commissioning engineers, ongoing operations integrity teams",codeRef:"ASTM E1934, NETA ATS Section 9.2 (infrared)"},{method:"Leak testing — chilled-water + immersion-cooling system commissioning",levels:"Level II",roleFit:"Cooling-system commissioning teams, immersion-tank QC",codeRef:"ASME V Article 10, ASME B31.9"}],skillGaps:[{gap:"Structural-steel weld inspectors holding AWS CWI without PAUT competence on the thick-section moment connections common in data center pre-action and seismic frames",impact:"Reliance on RT slows the critical path; or PAUT scans accepted on operator authority without code defence — owner-rep findings during turn-over."},{gap:"Liquid-cooling QC crews trained on hydronic ASME B31.9 only, encountering ASME B31.3 essential variables on generator-fuel and lube-oil systems",impact:"Acceptance criteria misapplied across pipe systems on a single project; rework at commissioning, schedule slip."},{gap:"Bus-bar joint inspectors without infrared thermography competence for commissioning + ongoing surveillance",impact:"Hot-spot escapes drive availability incidents — for a hyperscale operator each megawatt-hour of outage costs an order of magnitude more than the inspection programme it would prevent."},{gap:"Seismic-restraint inspectors trained on AISC steel acceptance without weld-specific NDT discipline",impact:"Seismic certification packages incomplete at commissioning; certificate of occupancy delayed."},{gap:"Recurrent training cadence set at SNT-TC-1A's 5-year default rather than the much shorter annual operator-warranty audit cycle typical at hyperscale operators",impact:"Hyperscale operator audits flag stale inspector qualification records — vendor-of-record status downgraded, future EPC awards lost."}],tracks:[{role:"Structural Steel + Seismic Weld QC",progression:"Level II UT + MT + VT, then PAUT Level II + AWS CWI prep",coreMethods:"UT, MT, VT, PAUT",hoursTotal:"200–240 instructor-led + 5-day CWI prep"},{role:"Bus-Bar + Switchgear Joint Inspector",progression:"Level II UT + MT + VT + infrared thermography",coreMethods:"UT, MT, VT, IR thermography",hoursTotal:"180–220 instructor-led"},{role:"Liquid-Cooling System Inspector",progression:"Level II UT + RT + MT + PT, then ASME B31.3 + B31.9 bridging module",coreMethods:"UT, RT, MT, PT",hoursTotal:"200–240 instructor-led"},{role:"Generator + Emergency Power Piping Inspector",progression:"Level II UT + RT + MT, then ASME B31.3 + NFPA 110 awareness",coreMethods:"UT, RT, MT",hoursTotal:"180–220 instructor-led"},{role:"Data Center Commissioning + IR Lead",progression:"Level II VT + UT thickness + IR thermography + leak testing",coreMethods:"VT, UT thickness, IR thermography, leak testing",hoursTotal:"140–180 instructor-led"}],pricing:[{headcount:"10–24 engineers",perHead:"Quote on request",notes:"Structural + electrical + cooling methods; AWS CWI prep included."},{headcount:"25–49 engineers",perHead:"Quote on request",notes:"Multi-method tracks across structural + electrical + cooling + commissioning."},{headcount:"50–99 engineers",perHead:"Quote on request",notes:"Multi-site hyperscale EPC programme; dedicated lead instructor."},{headcount:"100+ engineers",perHead:"Quote on request",notes:"Multi-region hyperscale annual contract; operator-specific written-practice bridging included."}],deliveryNote:"Data center cohorts are dominated by hybrid delivery, with structural-steel and bus-bar practicals running at the EPC's fabrication shop and commissioning practicals running on-site at the data center during pre-IST (integrated systems test). Theory on the LMS during design + procurement, practicals scheduled against the EPC critical path. AWS CWI prep is delivered as a 5-day intensive timed to the candidate's CWI exam window.",complianceFootnote:"Hyperscale data center operators (AWS, Microsoft Azure, Google Cloud, Meta, Equinix, Digital Realty) all run vendor-of-record audits to slightly different layouts but ask for the same underlying evidence — SNT-TC-1A written practice, AWS CWI credentials on welding inspectors, AWS D1.1 / D1.6 / B31.3 / B31.9 acceptance criteria correctly applied, vision and OJT logs current. Our delivery captures all of that automatically and exports it in the layout the hyperscale operator's facilities engineering team expects.",caseStudy:{headline:"Hyperscale EPC — US Sunbelt region — 56-engineer multi-method cohort, 10-week programme",body:"A hyperscale EPC ramping a multi-campus deployment in the US Sunbelt needed to certify 56 in-house QC engineers across UT Level II, MT/PT Level II, VT Level II, PAUT Level II for structural moment connections, and seed 18 candidates for AWS CWI ahead of a sequenced 8-data-hall campus build-out. Atlantis NDT delivered a hybrid cohort over 10 weeks: 5 weeks LMS theory in parallel with foundation construction, 4 weeks on-site practical at the campus during structural-steel erection, then a 1-week CWI prep block timed to the next AWS exam window. First-attempt CWI pass rate was 16 of 18; the two re-takes passed inside the standard window. The hyperscale operator's facilities engineering vendor-of-record audit closed the deployment with no inspector-qualification findings, and total per-head cost landed 28% below the open-enrolment route the EPC had budgeted."},cityLinks:[{slug:"houston",label:"Houston"},{slug:"dubai",label:"Dubai"}],wordCountHint:"Data center NDT corporate training is a buyer pattern unique among the verticals we serve — hyperscale operators (AWS, Microsoft Azure, Google Cloud, Meta, Equinix) deploy capital at a pace and scale that compresses the schedule for inspector qualification into a much tighter window than oil &amp; gas or aerospace, while at the same time running operator-warranty audits with much higher cadence than the SNT-TC-1A 5-year default. Our data center cohorts are built for the EPCs actually building the hyperscale campuses (Turner Construction, DPR Construction, Mortenson, Whiting-Turner, Holder Construction, Skanska, Clayco, Fortis, Linesight) and the colocation and edge operators (Equinix, Digital Realty, Iron Mountain, CyrusOne, QTS, CoreSite, EdgeConneX). The code-stack for data center NDT spans more inspection disciplines than any single industrial vertical — AWS D1.1 for structural steel (the moment frames and seismic restraints), AWS D1.6 for stainless steel (data hall cooling), ASME B31.3 for process piping (generator fuel and lube), ASME B31.9 for building-services piping (chilled water, condenser water, hot water), ASME Section V for inspection methods, and the electrical-systems toolkit (NETA ATS, NFPA 70, IEC 61936-1) for bus-bar and switchgear acceptance. Our cohorts map onto that stack rather than fighting against it — we run a single integrated written practice that covers all five code references and we deliver bridging modules that map between them rather than treating them as separate certification tracks. The skill gap that dominates data center training procurement is the gap between structural-steel inspectors with AWS CWI and the PAUT competence needed for thick-section moment connections on seismic frames. A single PAUT scan refusal on a critical-path moment connection can slip the construction critical path by days at a time, and at hyperscale economics that translates directly into months of delayed revenue. The second skill gap, especially common at colocation operators, is the gap between hydronic ASME B31.9 piping competence and the ASME B31.3 essential-variable discipline required for generator fuel and lube-oil systems. Engineers who have spent careers on building-services piping frequently misapply Section IX qualification rules on B31.3 systems. Our bridging module addresses that directly. The third area where data center diverges from traditional NDT verticals is the integration of infrared thermography into the commissioning and ongoing operations toolkit — bus-bar joint inspection at energisation is the highest-leverage IR application in any industrial setting because each megawatt-hour of unplanned outage at a hyperscale data center costs an order of magnitude more than the IR survey it would prevent. Our IR thermography track is delivered as both a commissioning module and an ongoing-operations module so the same engineers can carry the qualification through to data hall operations. Send the campus phase (foundation / structural / mechanical / commissioning / operations), the operator audit cycle, and headcount — we respond inside two business days with a written training plan and indicative quote."};function l(){return e.jsx(t,{config:i})}export{l as default};
